    let event = tokio::time::timeout(Duration::from_secs(2), events.recv())
        .await
        .unwrap();
    assert!(
        matches!(event,Some(BodyEvent::Frame(f)) if f.changes.iter().any(|c|matches!(c,BodyChange::Baseline)))
    );
