#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn snapshot_with_running_turn_captures_new_message_only() {
    use multi_agents_manager_lib::services::tps::{
        body_runtime::CaptureService, estimate_store::CaptureGate, reference::count_reference,
    };
    let (io, mut peer) = ScriptedPeer::new();
    let adapter = Arc::new(DesktopIpcAdapter::new(
        Arc::new(StaticConnector::new(io)),
        caps_open_profile(),
    ));
    let db = shared_conn();
    let gate = CaptureGate::new(true);
    let key = ThreadKey {
        host_id: "local".into(),
        thread_id: "00000000-0000-4000-8000-000000000031".into(),
    };
    let (_tx, rx) = tokio::sync::watch::channel(vec![key.clone()]);
    let service =
        CaptureService::start_for_test(adapter.clone(), gate, db.clone(), rx, "fixture".into());
    let state = serde_json::json!({"turns":[],"requests":[],"threadRuntimeStatus":{"type":"active"},"turnHistory":{"history":{"isComplete":true,"islands":[{"entries":[{"value":"turn:x"}]}],"entitiesByKey":{"turn:x":{"turnId":"x","status":"inProgress","items":[{"type":"agentMessage","id":"old","text":"historical output"},{"type":"reasoning","id":"r","summary":[{"text":""}]}]}}}}});
    drive_ensure_state(&mut peer, &key.thread_id, 7, state, true).await;
    let patches = vec![
        serde_json::json!([{"op":"replace","path":["turnHistory","history","entitiesByKey","turn:x","items",1,"summary",0,"text"],"value":"synthetic reasoning"}]),
        serde_json::json!([{"op":"add","path":["turnHistory","history","entitiesByKey","turn:x","items",1],"value":{"type":"agentMessage","id":"new","text":""}}]),
        serde_json::json!([{"op":"replace","path":["turnHistory","history","entitiesByKey","turn:x","items",1,"text"],"value":"hello"}]),
        serde_json::json!([{"op":"replace","path":["turnHistory","history","entitiesByKey","turn:x","items",1,"text"],"value":"hello world"}]),
        serde_json::json!([{"op":"add","path":["turnHistory","history","entitiesByKey","turn:x","items",1,"completedAtMs"],"value":1234},{"op":"add","path":["turnHistory","history","entitiesByKey","turn:x","durationMs"],"value":4000},{"op":"add","path":["turnHistory","history","entitiesByKey","turn:x","agentMessageCompletedAtMsById"],"value":{"new":1234}}]),
        serde_json::json!([{"op":"replace","path":["turnHistory","history","entitiesByKey","turn:x","status"],"value":"completed"}]),
    ];
    for (i, patch) in patches.into_iter().enumerate() {
        let base = 7 + i as u64;
        peer.send(&serde_json::json!({"type":"broadcast","method":"thread-stream-state-changed","sourceClientId":"owner-1","params":{"conversationId":key.thread_id,"change":{"type":"patches","baseRevision":base,"revision":base+1,"patches":patch}}})).await;
        tokio::time::timeout(Duration::from_secs(2), async {
            while adapter.projection(&key).await.revision != Some(base + 1) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .unwrap();
    }
    tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            if db
                .lock()
                .unwrap()
                .query_row("SELECT COUNT(*) FROM tps_body_estimate", [], |r| {
                    r.get::<_, i64>(0)
                })
                .unwrap()
                == 1
            {
                break;
            }
            tokio::task::yield_now().await;
        }
    })
    .await
    .expect("new message captured");
    assert_eq!(
        db.lock()
            .unwrap()
            .query_row("SELECT reference_tokens FROM tps_body_estimate", [], |r| {
                r.get::<_, i64>(0)
            })
            .unwrap(),
        count_reference("hello world").unwrap() as i64
    );
    service.shutdown().await;
    adapter.shutdown().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 6)]
async fn stopping_capture_does_not_deadlock_mirror_and_database() {
    use multi_agents_manager_lib::services::{
        tps::{
            body_runtime::CaptureService,
            estimate_store::{set_estimate_enabled_with_lock, CaptureGate},
        },
        usage::{model::UsageSettings, settings::save_with_gate_and_lock},
    };
    use std::sync::atomic::{AtomicBool, Ordering};
    for master in [true, false] {
        let (io, mut peer) = ScriptedPeer::new();
        let adapter = Arc::new(DesktopIpcAdapter::new(
            Arc::new(StaticConnector::new(io)),
            caps_open_profile(),
        ));
        let db = shared_conn();
        let gate = CaptureGate::new(true);
        let key = ThreadKey {
            host_id: "local".into(),
            thread_id: "00000000-0000-4000-8000-000000000032".into(),
        };
        let (_tx, rx) = tokio::sync::watch::channel(vec![key.clone()]);
        let service = CaptureService::start_for_test(
            adapter.clone(),
            gate.clone(),
            db.clone(),
            rx,
            "fixture".into(),
        );
        drive_ensure(&mut peer, &key.thread_id, vec![], "idle").await;
        adapter.ensure_thread(&key).await.unwrap();
        let (project_entered_tx, project_entered_rx) = tokio::sync::oneshot::channel();
        let entered = Arc::new(StdMutex::new(Some(project_entered_tx)));
        let (resume_tx, resume_rx) = std::sync::mpsc::channel();
        let resume = Arc::new(StdMutex::new(resume_rx));
        let db_probe = db.clone();
        let success = Arc::new(AtomicBool::new(false));
        let success2 = success.clone();
        adapter.set_auto_adapt_gate(Some(Arc::new(move || {
            if let Some(tx) = entered.lock().unwrap().take() {
                let _ = tx.send(());
                let _ = resume.lock().unwrap().recv_timeout(Duration::from_secs(3));
                success2.store(db_probe.try_lock().is_ok(), Ordering::SeqCst);
            }
            true
        })));
        let a = adapter.clone();
        let k = key.clone();
        let projection = tokio::spawn(async move { a.projection(&k).await });
        tokio::time::timeout(Duration::from_secs(3), project_entered_rx)
            .await
            .expect("projection reaches policy under mirror lock")
            .unwrap();
        let (producer_tx, mut producer_rx) = tokio::sync::mpsc::unbounded_channel();
        adapter.set_caps_observe_gate(Some(Arc::new(move |path| {
            if path == "state_changed" {
                let _ = producer_tx.send(());
            }
        })));
        peer.send(&serde_json::json!({"type":"broadcast","method":"thread-stream-state-changed","sourceClientId":"owner-1","params":{"conversationId":key.thread_id,"change":{"type":"patches","baseRevision":7,"revision":8,"patches":[{"op":"add","path":["turnHistory","history","entitiesByKey","turn:new"],"value":{"turnId":"new","status":"inProgress","items":[]}}]}}})).await;
        tokio::time::timeout(Duration::from_secs(3), producer_rx.recv())
            .await
            .expect("producer reached mirror wait")
            .unwrap();
        let db2 = db.clone();
        let gate2 = gate.clone();
        let stopped = tokio::task::spawn_blocking(move || {
            if master {
                save_with_gate_and_lock(
                    &db2,
                    &UsageSettings {
                        enabled: false,
                        ..Default::default()
                    },
                    &gate2,
                )
            } else {
                set_estimate_enabled_with_lock(&db2, false, &gate2)
            }
        });
        tokio::time::timeout(Duration::from_secs(3), async {
            while gate.permit().is_some() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("stop invalidates generation");
        resume_tx.send(()).unwrap();
        tokio::time::timeout(Duration::from_secs(3), projection)
            .await
            .expect("projection ends")
            .unwrap();
        tokio::time::timeout(Duration::from_secs(3), stopped)
            .await
            .expect("stop ends")
            .unwrap()
            .unwrap();
        assert!(
            success.load(Ordering::SeqCst),
            "projection could not acquire database while capture drained"
        );
        adapter.set_auto_adapt_gate(None);
        adapter.set_caps_observe_gate(None);
        assert_eq!(adapter.projection(&key).await.revision, Some(8));
        assert!(
            !peer_has_traffic(&mut peer).await,
            "remote follow remains in place"
        );
        service.shutdown().await;
        adapter.shutdown().await;
    }
}

#[tokio::test]
async fn pr202_first_snapshot_reconciles_old_answer() {
    use multi_agents_manager_lib::{
        database::dao::codex_interactions::StoredInteractionHint,
        remote::codex_evidence::StoreInteractionHints,
        services::codex_desktop_ipc::{
            async_question::{
                BatchWriteReport, HintStoreError, InteractionHintStore, InteractionState,
            },
            hint_commit::HintCommitPermit,
            hint_state::VersionedHint,
            types::ThreadProjection,
        },
    };

    // 固定冷载窗口，确保只有后台重观察能触发收敛，实际读写仍走 SQLite。
    struct GatedHintStore {
        store: StoreInteractionHints,
        load_gate: StdMutex<Option<tokio::sync::oneshot::Receiver<()>>>,
    }

    impl InteractionHintStore for GatedHintStore {
        fn load(&self, thread_id: &str) -> Option<Vec<StoredInteractionHint>> {
            let gate = self.load_gate.lock().unwrap().take();
            if let Some(gate) = gate {
                gate.blocking_recv().ok()?;
            }
            self.store.load(thread_id)
        }

        fn begin_epoch(&self) -> Result<i64, HintStoreError> {
            self.store.begin_epoch()
        }

        fn write_batch(
            &self,
            epoch: i64,
            hints: &[VersionedHint],
            at_ms: i64,
            permit: &HintCommitPermit,
        ) -> Result<BatchWriteReport, HintStoreError> {
            self.store.write_batch(epoch, hints, at_ms, permit)
        }
    }

    let mut f = fixture_ipc_unknown_interrupt(vec![codex_app_session(THREAD)], false);
    {
        let conn = f.conn.lock().unwrap();
        conn.execute("INSERT INTO codex_interaction_hints (thread_id, source_turn_id, source_item_id, question_index, last_fact, updated_at) VALUES (?1, 'old-turn', 'old-item', 0, 'pending', 1)", [THREAD]).unwrap();
    }
    let deadline = tokio::time::Instant::now() + Duration::from_secs(15);
    let (release_load, load_gate) = tokio::sync::oneshot::channel();
    f.state
        .codex_control
        .adapter
        .set_interaction_hint_store(Some(Arc::new(GatedHintStore {
            store: StoreInteractionHints::new(DeviceStore::Owned(f.conn.clone())),
            load_gate: StdMutex::new(Some(load_gate)),
        })));
    let mut published = f.state.codex_control.adapter.subscribe();
    let mut peer = f.peer.take().unwrap();
    let app = f.app.clone();
    let task = tokio::spawn(async move {
        app.oneshot(req(
            "GET",
            &format!("/m/api/v1/codex/thread?session_id={THREAD}"),
            Some(COOKIE),
            None,
        ))
        .await
        .unwrap()
    });
    tokio::time::timeout_at(deadline, async {
        handshake(&mut peer, "owner-1").await;
        let disc = peer.recv().await;
        peer.send(&discovery_response(
            disc["requestId"].as_str().unwrap(),
            "owner-1",
        ))
        .await;
        let follow = peer.recv().await;
        assert_eq!(follow["method"], "thread-stream-following-changed");
        let old_key = r#"["request_user_input_async","old-item",0]"#;
        let envelope = format!("<send_user_message_question_reply>\n[{{\"questionItemId\":{},\"question\":\"旧题\",\"answer\":\"甲\"}}]\n</send_user_message_question_reply>", serde_json::to_string(old_key).unwrap());
        peer.send(&serde_json::json!({
            "type":"broadcast", "method":"thread-stream-state-changed", "version":11,
            "sourceClientId":"owner-1", "params": {"conversationId":THREAD,"hostId":"local",
            "change":{"type":"snapshot","revision":9,"conversationState":{
              "turns":[],"requests":[],"threadRuntimeStatus":{"type":"idle"},
              "turnHistory":{"history":{"isComplete":true,"entitiesByKey":{
                "turn:new":{"turnId":"new","status":"completed","items":[{"type":"agentMessage","id":"new-item","text":"新题","phase":"final_answer","delivery":"async","questions":[{"title":"新题","options":["甲"]}]}]},
                "turn:answer":{"turnId":"answer","status":"completed","items":[{"type":"userMessage","id":"answer-item","content":[{"type":"text","text":envelope,"text_elements":[]}]}]}
              },"islands":[{"id":"i","entries":[{"key":"turn:new","value":"turn:new"},{"key":"turn:answer","value":"turn:answer"}]}]}}
            }}}})).await;
    })
    .await
    .expect("hint 冷载期间必须完成握手、发现、follow 和快照发送");
    let check_published = |p: &ThreadProjection| {
        assert!(
            p.async_questions
                .iter()
                .filter(|q| q.source_item_id == "old-item")
                .all(|q| q.state == InteractionState::Unknown),
            "广播中的旧题必须保持 Unknown: {:?}",
            p.async_questions
        );
        assert!(
            p.async_questions
                .iter()
                .any(|q| q.source_item_id == "new-item"
                    && q.state == InteractionState::TemporarilyBlocked),
            "广播必须保留暂不可答的新题: {:?}",
            p.async_questions
        );
    };
    tokio::time::timeout_at(deadline, async {
        loop {
            let p = published.recv().await.unwrap();
            if p.thread_id == THREAD && p.revision == Some(9) {
                check_published(&p);
                break;
            }
        }
    })
    .await
    .expect("hint 冷载期间必须发布 revision 9 首帧");
    let initial: serde_json::Value = tokio::time::timeout_at(deadline, async {
        let response = task.await.unwrap();
        assert_eq!(response.status(), 200);
        serde_json::from_str(&body_string(response).await).unwrap()
    })
    .await
    .expect("首个 GET 必须在 hint 冷载期间返回");
    let initial_questions = initial["asyncQuestions"].as_array().unwrap();
    assert!(
        initial_questions
            .iter()
            .filter(|q| q["sourceItemId"] == "old-item")
            .all(|q| q["state"] == "unknown"),
        "首个 GET 中的旧题必须保持 Unknown: {initial}"
    );
    assert!(
        initial_questions
            .iter()
            .any(|q| q["sourceItemId"] == "new-item" && q["state"] == "temporarily_blocked"),
        "首个 GET 必须保留新题: {initial}"
    );

    release_load.send(()).unwrap();
    // 继续用原订阅，避免补取投影触发写穿并掩盖后台漏发或漏写。
    tokio::time::timeout_at(deadline, async {
        loop {
            let p = published.recv().await.unwrap();
            if p.thread_id == THREAD && p.revision == Some(9) {
                check_published(&p);
                if p.async_questions
                    .iter()
                    .any(|q| q.source_item_id == "old-item")
                {
                    break;
                }
            }
        }
    })
    .await
    .expect("hint 装载后必须主动重发同 revision 的旧题 Unknown");
    tokio::time::timeout_at(deadline, async {
        loop {
            match f.conn.try_lock() {
                Ok(conn) => {
                    let fact: String = conn.query_row("SELECT last_fact FROM codex_interaction_hints WHERE thread_id=?1 AND source_turn_id='old-turn' AND source_item_id='old-item' AND question_index=0", [THREAD], |r| r.get(0)).unwrap();
                    if fact == "unknown" {
                        break;
                    }
                    assert_eq!(fact, "pending", "后台写入了意外的旧题状态");
                }
                Err(std::sync::TryLockError::WouldBlock) => {}
                Err(err) => panic!("内存 SQLite 锁不可用: {err}"),
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("后台必须把旧题 Unknown 提交到 SQLite");

    install_async_answer_contract(&f);
    let key = f.thread_key();
    let p = tokio::time::timeout_at(deadline, f.state.codex_control.adapter.projection(&key))
        .await
        .expect("注入能力证据后必须返回投影");
    assert_eq!(
        p.async_questions
            .iter()
            .find(|q| q.source_item_id == "new-item")
            .unwrap()
            .state,
        InteractionState::Pending
    );
    assert_eq!(
        p.async_questions
            .iter()
            .find(|q| q.source_item_id == "old-item")
            .unwrap()
            .state,
        InteractionState::Unknown
    );
}

// 运行中正式答题：只用合成快照、内存账本和 duplex 假 peer。
fn install_active_async_answer_contract(f: &Fixture) {
    use multi_agents_manager_lib::services::codex_desktop_ipc::capability::{
        CodexOperation, ContractMatch, DesktopContractEvidence, CONTRACT_RULE_VERSION,
    };
    let mut matches = std::collections::BTreeMap::new();
    matches.insert(
        CodexOperation::AsyncAnswerActive,
        ContractMatch {
            method: "thread-follower-steer-turn".into(),
            base_version: 1,
            request_rule: "conversationId+clientUserMessageId+input+attachments+restoreMessage"
                .into(),
            response_rule: "result.result.turnId".into(),
            semantic_rule: "async answer envelope via steer-turn v1".into(),
        },
    );
    f.state
        .codex_control
        .adapter
        .set_contract_evidence_snapshot(DesktopContractEvidence {
            probe_key: "macos|26.1021.31345|cli|1".into(),
            package_sha256: "c".repeat(64),
            rule_version: CONTRACT_RULE_VERSION,
            matches,
            package_size: None,
            package_mtime_ms: None,
        });
}

async fn active_async_projection(f: &Fixture) -> serde_json::Value {
    let response = f
        .app
        .clone()
        .oneshot(req(
            "GET",
            &format!("/m/api/v1/codex/thread?session_id={THREAD}"),
            Some(COOKIE),
            None,
        ))
        .await
        .unwrap();
    assert_eq!(response.status(), 200);
    serde_json::from_str(&body_string(response).await).unwrap()
}

fn assert_active_steer_frame(frame: &serde_json::Value, questions: &[(String, String)]) -> String {
    assert_eq!(frame["method"], "thread-follower-steer-turn");
    assert_eq!(frame["version"], 1);
    let params = &frame["params"];
    assert_eq!(params["conversationId"], THREAD);
    assert!(params.get("expectedTurnId").is_none());
    assert!(params.get("raw").is_none());
    assert_eq!(params["attachments"], serde_json::json!([]));
    let cmid = params["clientUserMessageId"].as_str().unwrap().to_owned();
    assert!(!cmid.is_empty());
    assert_eq!(params["restoreMessage"]["id"], cmid);
    let input = params["input"].as_array().unwrap();
    assert_eq!(input.len(), 1);
    assert_eq!(input[0]["type"], "text");
    assert_eq!(input[0]["text_elements"], serde_json::json!([]));
    let text = input[0]["text"].as_str().unwrap();
    let parsed = multi_agents_manager_lib::services::codex_desktop_ipc::async_question::parse_answer_envelope(text).expect("正式信封");
    assert_eq!(parsed.len(), questions.len());
    for (i, entry) in parsed.iter().enumerate() {
        assert_eq!(entry.question_item_id, questions[i].0);
        assert_eq!(entry.question, format!("问题{}", i + 1));
        assert_eq!(entry.answer, "甲");
    }
    assert_eq!(params["restoreMessage"]["text"], text);
    assert_eq!(params["restoreMessage"]["context"]["prompt"], text);
    assert_eq!(
        params["restoreMessage"]["context"]["turnTrigger"],
        "send_user_message_async_question"
    );
    cmid
}

async fn respond_active_steer(peer: &mut ScriptedPeer, frame: &serde_json::Value) {
    peer.send(&serde_json::json!({
        "type": "response", "requestId": frame["requestId"],
        "resultType": "success", "method": "thread-follower-steer-turn",
        "handledByClientId": "owner-1", "result": {"result": {"turnId": "turn-a"}}
    }))
    .await;
}

